{
  "schema_version": "sections_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "sections": [
        {
          "section_id": 1,
          "title": "The Vending Machine Incident",
          "intent": "Establish Arlo's mundane life and his transition to the game world via a comedic death.",
          "section_role": "setup",
          "target_scene_count": 2,
          "end_condition": "Arlo dies and begins the reincarnation process into Aethelgard Online."
        },
        {
          "section_id": 2,
          "title": "The Character Sheet Disaster",
          "intent": "Introduce the game mechanics and Arlo's devastatingly low Luck stat.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Arlo confirms his -999 Luck has triggered an 'Overflow' status on his character sheet."
        },
        {
          "section_id": 3,
          "title": "The Slime Sprint",
          "intent": "Demonstrate the 'Crit Hit & Run' exploit through a low-stakes combat encounter.",
          "section_role": "development",
          "target_scene_count": 3,
          "end_condition": "Arlo successfully kills a slime while running away, realizing his retreat-based attacks are guaranteed criticals."
        }
      ]
    },
    {
      "chapter_id": 2,
      "sections": [
        {
          "section_id": 1,
          "title": "Grinding the Coward's Way",
          "intent": "Show Arlo refining his 'retreat-strike' technique on tutorial mobs to gather basic gear.",
          "section_role": "development",
          "target_scene_count": 3,
          "end_condition": "Arlo reaches the Tutorial Guardian's gate equipped with basic gear and a plan."
        },
        {
          "section_id": 2,
          "title": "The Guardian's Arena",
          "intent": "A high-intensity battle where Arlo must use his exploit to defeat a boss designed to be impossible for solo players.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "The Tutorial Guardian is defeated by a final, retreating blow."
        },
        {
          "section_id": 3,
          "title": "Loot and Logistics",
          "intent": "Arlo claims the massive loot drop and upgrades his mobility to better facilitate his combat style.",
          "section_role": "resolution",
          "target_scene_count": 3,
          "end_condition": "Arlo purchases the 'Dash' skill book and prepares to enter the main hub city."
        }
      ]
    },
    {
      "chapter_id": 3,
      "sections": [
        {
          "section_id": 1,
          "title": "The Hub City Hustle",
          "intent": "Arlo enters Oakhaven and attempts to liquidate his high-tier tutorial loot without raising suspicion.",
          "section_role": "setup",
          "target_scene_count": 4,
          "end_condition": "Arlo's attempt to sell rare items attracts the attention of the 'Min-Maxers' guild."
        },
        {
          "section_id": 2,
          "title": "Interrogation by the Elite",
          "intent": "The guild leaders confront Arlo, suspecting him of using third-party hacking software.",
          "section_role": "pressure",
          "target_scene_count": 4,
          "end_condition": "The guild leader, Vex, corners Arlo and demands a live demonstration of his 'skills'."
        },
        {
          "section_id": 3,
          "title": "The Ultimatum",
          "intent": "Arlo negotiates his survival by accepting a challenge that forces him to reveal his exploit.",
          "section_role": "transition",
          "target_scene_count": 4,
          "end_condition": "Arlo agrees to the 'Trial of the Coward' to prove his innocence and gain guild protection."
        }
      ]
    },
    {
      "chapter_id": 4,
      "sections": [
        {
          "section_id": 1,
          "title": "The Dungeon Entrance",
          "intent": "Set the scene for the dungeon trial and introduce Jax, the guild's skeptical scout.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Arlo and Jax enter the Sunken Crypts to begin the no-frontal-damage challenge."
        },
        {
          "section_id": 2,
          "title": "The Reverse Gauntlet",
          "intent": "Arlo clears the dungeon using his 'Yellow Streak' style, confusing and impressing Jax.",
          "section_role": "action",
          "target_scene_count": 5,
          "end_condition": "The final room of the crypt is cleared without Arlo ever facing an enemy head-on."
        },
        {
          "section_id": 3,
          "title": "The Glitch Discovery",
          "intent": "The duo finds an anomaly in the dungeon that leads to a hidden, unstable zone.",
          "section_role": "mystery",
          "target_scene_count": 3,
          "end_condition": "Arlo identifies the entrance to the 'System Glitch' zone at the back of the boss room."
        }
      ]
    },
    {
      "chapter_id": 5,
      "sections": [
        {
          "section_id": 1,
          "title": "The Red Text Warning",
          "intent": "The System announces a patch to fix exploits, putting Arlo's existence at risk.",
          "section_role": "inciting_incident",
          "target_scene_count": 3,
          "end_condition": "The emergency maintenance countdown begins, giving Arlo one hour to reach the Source Code altar."
        },
        {
          "section_id": 2,
          "title": "The High-Level Shortcut",
          "intent": "Arlo and Jax must navigate a dangerous high-level map to reach the altar before the server reset.",
          "section_role": "action",
          "target_scene_count": 5,
          "end_condition": "They successfully cross the Deadlands, narrowly avoiding lethal high-level mobs."
        },
        {
          "section_id": 3,
          "title": "The Glitch Zone Threshold",
          "intent": "They arrive at the heart of the glitch zone where the laws of the game are breaking down.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "Arlo and Jax reach the entrance of the Source Code chamber as the countdown hits ten minutes."
        }
      ]
    },
    {
      "chapter_id": 6,
      "sections": [
        {
          "section_id": 1,
          "title": "The Sentinel Awakens",
          "intent": "The final boss of the glitch zone engages Arlo, specifically designed to counter mobile players.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "The Zone Sentinel initiates its 'anti-runner' pursuit protocol."
        },
        {
          "section_id": 2,
          "title": "The Infinite Retreat",
          "intent": "A desperate chase where Arlo must use every mobility trick to survive the Sentinel's attacks.",
          "section_role": "action",
          "target_scene_count": 6,
          "end_condition": "Arlo keeps the Sentinel at bay as the patch timer reaches its final sixty seconds."
        },
        {
          "section_id": 3,
          "title": "The Final Seconds",
          "intent": "Arlo reaches the altar and attempts to register his 'Bug' as a permanent feature.",
          "section_role": "climax",
          "target_scene_count": 4,
          "end_condition": "Arlo activates the altar as the world fades to white for the maintenance update."
        }
      ]
    },
    {
      "chapter_id": 7,
      "sections": [
        {
          "section_id": 1,
          "title": "The Log-In",
          "intent": "Arlo wakes up in the post-patch world and checks his status for any 'fixes'.",
          "section_role": "resolution",
          "target_scene_count": 3,
          "end_condition": "Arlo confirms his stats are intact and he has been granted the 'Unfixable One' title."
        },
        {
          "section_id": 2,
          "title": "The New Reality",
          "intent": "Arlo discovers that the patch has introduced 'Invulnerable' mobs that only he can damage.",
          "section_role": "development",
          "target_scene_count": 3,
          "end_condition": "Arlo kills a new 'Admin-Tier' mob that other players find impossible to touch."
        },
        {
          "section_id": 3,
          "title": "The Target on His Back",
          "intent": "Establish the new status quo where Arlo is the game's most valuable and hunted player.",
          "section_role": "hook",
          "target_scene_count": 3,
          "end_condition": "The major guilds surround Arlo, realizing he is the key to the new endgame content."
        }
      ]
    }
  ]
}

